INSERT INTO `categories` VALUES (1,'Period Panties','period-panties','High absorbency, multi-layer leakproof period underwear engineered for heavy, medium, and light flow days.','cat_period_panties.jpg','cat_period_panties.jpg',1,'active',NULL,NULL,'2026-10-16 19:03:25'),(2,'Everyday Panties','everyday-panties','Buttery-soft, breathable bamboo and micro-modal panties designed for zero wedgies and daily all-day comfort.','cat_everyday_panties.jpg','cat_everyday_panties.jpg',2,'active',NULL,NULL,'2026-10-16 19:03:25'),(3,'Period Kits','period-kits','Curated confidence boxes, starter hampers, and travel packs with period underwear, pads, and hygiene essentials.','cat_period_kits.jpg','cat_period_kits.jpg',3,'active',NULL,NULL,'2026-10-16 19:03:25'),(4,'Pads & Liners','pads-and-liners','Rash-free 100% certified organic cotton pads, extra-long overnight wings, and biodegradable ultra-slim panty liners.','cat_pads_liners.jpg','cat_pads_liners.jpg',4,'active',NULL,NULL,'2026-10-16 19:03:25'),(5,'Intimate Care','intimate-care','Dermatologically tested pH 3.8 foaming washes, soothing anti-chafing sticks, and natural period panty stain cleansers.','cat_intimate_care.jpg','cat_intimate_care.jpg',5,'active',NULL,NULL,'2026-10-16 19:03:25'),(6,'Combos & Value Packs','combos','Multi-packs and curated bundles designed to give you maximum value while building your complete period routine.','cat_combos.jpg','cat_combos.jpg',6,'active',NULL,NULL,'2026-10-16 19:03:25');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;

