INSERT INTO `cms_pages` VALUES (1,'About AFOREHEALTH','about-us','<h2>Our Purpose: Comfort. Care. Confidence.</h2><p>AFOREHEALTH was created to bridge a vital gap in Indian women\'s wellness: everyday intimate care that is comfortable, body-positive, scientifically formulated, and deeply respectful of personal privacy.</p><p>For too long, women in India have had to compromise between scratchy, synthetic innerwear, plastic-laden pads that cause painful rashes, and the unnecessary stigma around purchasing intimate hygiene products.</p><p>We believe every woman deserves pure comfort, skin-friendly fabrics, sustainable period alternatives, and seamless delivery without anxiety. That is why every AFOREHEALTH product is tested for skin friendliness, manufactured using premium modal and organic cotton, and shipped in 100% discreet packaging.</p>','About AFOREHEALTH | Women\'s Intimate & Period Care India','Learn how AFOREHEALTH is revolutionizing women\'s intimate health and period care in India with comfort, privacy, and body-friendly materials.',1,'2026-10-08 04:21:41','2026-10-08 04:21:41'),(2,'Privacy & Discreet Shipping Policy','privacy-policy','<h2>Your Privacy Matters Most</h2><p>At AFOREHEALTH, privacy is not an afterthought—it is foundational to everything we do.</p><h3>Discreet Packaging Guarantee</h3><p>Every single parcel is shipped in plain, unmarked, tamper-evident external packaging. The shipping label only lists the delivery address and courier tracking barcode; it contains zero descriptions of intimate products or period care items.</p><h3>Data Protection</h3><p>We only use your mobile number for fast OTP authentication and essential order delivery notifications. We will never sell, rent, or spam your contact information.</p>','Discreet Packaging & Privacy Policy | AFOREHEALTH','Our 100% discreet packaging guarantee and transparent privacy policy for Indian women.',1,'2026-10-08 04:21:41','2026-10-08 04:21:41'),(3,'Shipping & Delivery Policy','shipping-policy','<h2>Fast & Reliable Nationwide Delivery</h2><p>We partner with premier Indian logistics carriers including Delhivery, Blue Dart, DTDC, and Shiprocket to ensure your orders reach you swiftly and safely.</p><ul><li><strong>Free Express Shipping:</strong> Available on all prepaid and COD orders above ₹599.</li><li><strong>Standard Shipping:</strong> A flat ₹50 shipping fee applies on orders below ₹599.</li><li><strong>Dispatch Time:</strong> Orders placed before 2:00 PM are dispatched the same day.</li><li><strong>Delivery Timelines:</strong> 2-4 business days for major cities, 3-6 business days for rest of India.</li></ul>','Shipping Policy | AFOREHEALTH India','Shipping timelines, free delivery threshold, and courier details across India.',1,'2026-10-08 04:21:41','2026-10-08 04:21:41'),(4,'Return, Exchange & Refund Policy','return-policy','<h2>Intimate Hygiene & Return Guidelines</h2><p>To uphold the highest personal hygiene and safety benchmarks for all customers, innerwear, panties, menstrual cups, and opened personal washes cannot be returned once delivered.</p><h3>Eligibility for Replacement or Refund:</h3><ul><li>Product received was damaged or broken in transit.</li><li>Wrong size or incorrect item delivered due to fulfilling error.</li><li>Manufacturing defect reported within 48 hours of delivery.</li></ul><p>To initiate a claim, navigate to your My Orders dashboard or connect with our WhatsApp support with an unboxing photo.</p>','Return & Refund Policy | AFOREHEALTH','Understand our hygiene-compliant return, replacement, and refund policy.',1,'2026-10-08 04:21:41','2026-10-08 04:21:41'),(5,'Terms & Conditions','terms-conditions','<h2>Terms of Service</h2><p>Welcome to AFOREHEALTH. By accessing our platform, placing orders, or joining our wellness community, you agree to comply with our commercial terms and conditions governed under Indian consumer and cyber laws.</p><p>All prices are quoted in Indian Rupees (₹ INR) inclusive of applicable GST taxes. Orders are subject to stock availability and address serviceability.</p>','Terms & Conditions | AFOREHEALTH','Legal terms and conditions for using AFOREHEALTH website and services.',1,'2026-10-08 04:21:41','2026-10-08 04:21:41'),(6,'Complete Size & Fit Guide','size-guide','<h2>Find Your Perfect AFOREHEALTH Fit</h2><p>Comfortable intimate wear begins with the right fit. Use a soft measuring tape and keep it snug but not tight against your body.</p><h3>Period Panties & Briefs Size Chart (Inches)</h3><table class=\"table table-bordered\"><thead><tr><th>Size</th><th>Waist (Inches)</th><th>Hip (Inches)</th><th>Indian Dress Size</th></tr></thead><tbody><tr><td>XS</td><td>24 - 26</td><td>32 - 34</td><td>UK/IND 6</td></tr><tr><td>S</td><td>26 - 28</td><td>34 - 36</td><td>UK/IND 8</td></tr><tr><td>M</td><td>28 - 30</td><td>36 - 38</td><td>UK/IND 10</td></tr><tr><td>L</td><td>30 - 32</td><td>38 - 40</td><td>UK/IND 12</td></tr><tr><td>XL</td><td>32 - 35</td><td>40 - 43</td><td>UK/IND 14</td></tr><tr><td>XXL</td><td>35 - 38</td><td>43 - 46</td><td>UK/IND 16</td></tr></tbody></table>','Innerwear & Period Panty Size Guide | AFOREHEALTH','Comprehensive size guide and measurement chart for Indian women.',1,'2026-10-08 04:21:41','2026-10-08 04:21:41');
/*!40000 ALTER TABLE `cms_pages` ENABLE KEYS */;
UNLOCK TABLES;

