INSERT INTO `collections` VALUES (1,'Bestsellers','bestsellers','Our most loved and highest rated intimate care picks by 50,000+ Indian women.','HOT SELLER','coll_bestsellers.svg','active',1,'2026-10-16 19:03:25'),(2,'New Arrivals','new-arrivals','Freshly launched fabrics, moisture-wicking weaves, and new seasonal colorways.','JUST IN','coll_new_arrivals.svg','active',2,'2026-10-16 19:03:25'),(3,'Period Starter Kits','starter-kits','Everything you need to switch away from single-use plastic pads with total peace of mind.','VALUE PACK','coll_starters.svg','active',3,'2026-10-16 19:03:25'),(4,'Postpartum & High-Rise Care','postpartum-high-rise','Doctor-approved soothing recovery underwear engineered for postpartum bleeding.','RECOVERY','coll_postpartum.svg','active',4,'2026-10-16 19:03:25');
