LOCK TABLES `product_questions` WRITE;
/*!40000 ALTER TABLE `product_questions` DISABLE KEYS */;
INSERT INTO `product_questions` VALUES (1,1,2,'Can I wear these period panties overnight on my heaviest day without any pads?','Yes! Our UltraDry panties are engineered with a 4-layer breathable absorption gusset designed to hold up to 4 regular pads worth of liquid. They provide 360° leak guard even when sleeping on your side or back.',1,'approved','2026-10-08 05:55:05','2026-10-08 05:55:05'),(2,1,2,'How do I wash them to maintain the leakproof barrier?','Rinse immediately with cold water until the water runs clear, then machine or hand wash with gentle detergent. Avoid fabric softeners, bleach, or hot water tumble drying.',1,'approved','2026-10-08 05:55:05','2026-10-08 05:55:05'),(11,1,2,'Are these panties suitable for heavy flow nights?',NULL,NULL,'pending','2026-10-08 08:34:47','2026-10-08 08:34:47');
/*!40000 ALTER TABLE `product_questions` ENABLE KEYS */;
UNLOCK TABLES;

