  PRIMARY KEY (`id`),
  KEY `fk_video_product` (`product_id`),
  CONSTRAINT `fk_video_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
